p5.js sketch: interactive Lunda shading
Paste into the p5.js Web Editor. The sketch draws a 45° ray and colours each unit square it enters according to parity.
// Lunda shading: colour unit squares by (i+j) mod 2
// while a 45° ray travels between the pulli

let rows = 8, cols = 8;
let cell = 50;
let margin = 40;
let path = [];
let t = 0;

function setup() {
  createCanvas(cols*cell + 2*margin, rows*cell + 2*margin);
  generatePath();
}

function draw() {
  background(245);
  translate(margin, margin);

  // Draw all unit squares, coloured if visited
  let visited = {};
  let n = min(floor(t), path.length);
  for (let k = 0; k &lt; n; k++) {
    let i = floor(path[k].y / cell);
    let j = floor(path[k].x / cell);
    visited[i+","+j] = true;
  }

  for (let i = 0; i &lt; rows; i++) {
    for (let j = 0; j &lt; cols; j++) {
      if (visited[i+","+j]) {
        fill((i+j) % 2 === 0 ? 255 : 30);
      } else {
        fill(230);
      }
      stroke(180);
      rect(j*cell, i*cell, cell, cell);
    }
  }

  // Pulli
  fill(20); noStroke();
  for (let i = 0; i &lt;= rows; i++)
    for (let j = 0; j &lt;= cols; j++)
      circle(j*cell, i*cell, 6);

  // Ray
  noFill(); stroke(30,90,180); strokeWeight(2);
  beginShape();
  for (let k = 0; k &lt; n; k++) vertex(path[k].x, path[k].y);
  endShape();

  t += 0.8;
  if (t &gt; path.length + 30) t = 0;
}

function generatePath() {
  path = [];
  let x = 0.5*cell, y = 0.5*cell;
  let dx = 1, dy = 1;
  for (let s = 0; s &lt; 300; s++) {
    path.push({x, y});
    if (x + dx*cell*0.5 &lt; 0 || x + dx*cell*0.5 &gt; cols*cell) dx = -dx;
    if (y + dy*cell*0.5 &lt; 0 || y + dy*cell*0.5 &gt; rows*cell) dy = -dy;
    x += dx * cell * 0.5;
    y += dy * cell * 0.5;
  }
}

Recovering the curve as an Eulerian path
Hierholzer’s algorithm (or any Eulerian-circuit routine) applied to the graph defined by (B_M) yields the sequence of mid-points visited by the light ray. Connecting those points with 45° segments reproduces the polygonal path of the earlier ray-tracer.
p5.js visualisation of the Eulerian path
The sketch below draws the pulli, a few mid-edge vertices, and an animated Eulerian circuit that respects a simple mirror constraint. Paste it into the p5.js Web Editor.
// Visualise step-graph vertices and an Eulerian path
// (simplified for a 3x3 pulli grid)

let cell = 80;
let margin = 100;
let path = [];
let t = 0;

function setup() {
  createCanvas(500, 500);
  // Hard-coded Eulerian circuit on mid-points (illustrative)
  path = [
    {x: 0.5, y: 0}, {x: 1, y: 0.5}, {x: 1.5, y: 1},
    {x: 1, y: 1.5}, {x: 0.5, y: 2}, {x: 0, y: 1.5},
    {x: 0.5, y: 1}, {x: 1, y: 0.5}, {x: 0.5, y: 0}
  ];
}

function draw() {
  background(252);
  translate(margin, margin);

  // Pulli
  fill(20); noStroke();
  for (let i = 0; i &lt; 3; i++)
    for (let j = 0; j &lt; 3; j++)
      circle(j * cell, i * cell, 12);

  // Mid-edge vertices of the step graph
  fill(180, 40, 40);
  for (let p of path) circle(p.x * cell, p.y * cell, 7);

  // Animated Eulerian path
  noFill(); stroke(30, 100, 190); strokeWeight(2.5);
  beginShape();
  let n = min(floor(t), path.length);
  for (let k = 0; k &lt; n; k++)
    vertex(path[k].x * cell, path[k].y * cell);
  endShape();

  t += 0.15;
  if (t &gt; path.length + 20) t = 0;
}


